# cache.go (1.3 KB)
cat <<EOL > "cache.go"
package pufferpanel

import (
	"github.com/pufferpanel/pufferpanel/v3/config"
	"sync"
	"time"
)

type cacheMessage struct {
	msg  []byte
	time int64
}

type MemoryCache struct {
	Buffer   []cacheMessage
	Capacity int
	Size     int
	Lock     sync.RWMutex
}

func CreateCache() *MemoryCache {
	capacity := config.ConsoleBuffer.Value()
	if capacity <= 0 {
		capacity = 50
	}
	return &MemoryCache{
		Buffer:   make([]cacheMessage, 0),
		Capacity: capacity * 1024, //convert to KB
	}
}

func (c *MemoryCache) Read() (msg []byte, lastTime int64) {
	msg, lastTime = c.ReadFrom(0)
	return
}

func (c *MemoryCache) ReadFrom(startTime int64) (msg []byte, lastTime int64) {
	c.Lock.RLock()
	defer c.Lock.RUnlock()

	lastTime = time.Now().UnixMicro()

	msg = make([]byte, 0)

	for _, v := range c.Buffer {
		if v.time > startTime {
			msg = append(msg, v.msg...)
		}
	}

	return
}

func (c *MemoryCache) Write(b []byte) (n int, err error) {
	c.Lock.Lock()
	defer c.Lock.Unlock()
	n = len(b)

	//remove data until we've gotten small enough
	var pop cacheMessage
	for c.Size+n > c.Capacity {
		pop, c.Buffer = c.Buffer[0], c.Buffer[1:]
		c.Size = c.Size - len(pop.msg)
	}

	co := make([]byte, len(b))
	copy(co, b)

	c.Buffer = append(c.Buffer, cacheMessage{msg: co, time: time.Now().UnixMicro()})
	c.Size = c.Size + n
	return
}

EOL

# client.go (714 bytes)
cat <<EOL > "client.go"
package pufferpanel

import (
	"github.com/cavaliergopher/grab/v3"
	"github.com/mholt/archiver/v3"
	"github.com/pufferpanel/pufferpanel/v3/files"
	"net/http"
	"os"
)

var httpClient = &http.Client{}

func Http() *http.Client {
	return httpClient
}

func HttpGet(requestUrl string) (*http.Response, error) {
	return httpClient.Get(requestUrl)
}

func HttpExtract(requestUrl, directory string, archiveType archiver.Walker) error {
	//we will write this to temp so we can not keep so much in memory
	response, err := grab.Get(os.TempDir(), requestUrl)
	if err != nil {
		return err
	}
	defer os.Remove(response.Filename)

	err = files.Extract(nil, response.Filename, directory, "*", false, archiveType)
	return err
}

EOL

