# client/frontend/src/themes/default/_icons.scss (182.3 KB)
cat <<EOL > "client/frontend/src/themes/default/_icons.scss"
@use "sass:map";
@use "sass:meta";
@use "sass:string";

// slightly modified mdi scss
@font-face {
  font-family: 'Material Design Icons';
  src: url('/fonts/MaterialIcons.6.4.95.woff2') format('woff2');
  font-weight: normal;
  font-style: normal;
}

@mixin icon-base {
  display: inline-block;
  font: normal normal normal 24px 'Material Design Icons';
  font-size: inherit;
  text-rendering: auto; // optimizelegibility throws things off: mdi issue #1094
  line-height: inherit;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: var(--text);
}

@mixin icon {
  &::before {
    @include icon-base;
  }
}

.icon {
  @include icon;
}

@mixin icon-spin-base {
  animation: icon-spin 2s infinite linear;
}

@mixin icon-spin {
  &::before {
    animation: icon-spin 2s infinite linear;
  }
}

.icon-spin {
  @include icon-spin;
}

@keyframes icon-spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(359deg);
  }
}

.icon-blank::before {
  content: "\\F68C";
  visibility: hidden;
}

@function icon-char(\\$character-code) {
  @if meta.function-exists("selector-append") {
    @return string.unquote("\\"\\\\#{\\$character-code}\\"");
  }

  @if "\\\\#{'x'}" == "\\\\x" {
    @return str-slice("\\x", 1, 1) + \\$character-code;
  } @else {
    @return #{"\\"\\\\"}#{\\$character-code + "\\""};
  }
}

@mixin icon-name-base(\\$icon) {
  content: icon-char(map.get(\\$mdi-icons, \\$icon));
}

@mixin icon-name(\\$icon) {
  &::before {
    content: icon-char(map.get(\\$mdi-icons, \\$icon));
  }
}

