@use '../mixins' as *;
@use '../icons' as *;

.server .type {
  display: none;
}

.server-type-none .server {
  position: relative;
  padding-right: 4em !important;

  @mixin status-indicator {
    @include icon-base;
    position: absolute;
    top: 0.15em;
    right: 0.2em;
    display: block;
    font-size: 3em;
  }

  &[data-online="installing"]::before {
    @include status-indicator;
    @include icon-name-base(package-down);
    color: var(--primary);
  }

  &[data-online="online"]::before {
    @include status-indicator;
    @include icon-name-base(play-circle);
    color: var(--primary);
  }

  &[data-online="offline"]::before {
    @include status-indicator;
    @include icon-name-base(stop-circle);
    color: var(--text-disabled);
  }

  &[data-online="loading"]::before {
    @include status-indicator;
    @include icon-name-base(loading);
    @include icon-spin-base;
  }
}

\\$serverTypes: (
  '7days2die',
  'ark',
  'arma3',
  'csgo',
  'css',
  'dontstarvetogether',
  'eco',
  'factorio',
  'gmod',
  'hytale',
  'minecraft-bedrock',
  'minecraft-java',
  'rust',
  'satisfactory',
  'squad',
  'starbound',
  'terraria',
  'tf2',
  'valheim',
  'vintage-story',
  'zomboid'
);

@each \\$type in \\$serverTypes {
  .server-type-icon:not(.server-type-nobackground) .server-wrapper-#{\\$type} > a {
    background-image: url('/img/heros/' + \\$type + '.jpg');
    background-position: center center;
    background-size: 100%;
    display: block;
    border-radius: calc(var(--border-radius) + 1px);
  }
}

.server-type-icon:not(.server-type-nobackground) {
  .server-satisfactory, .server-csgo, .server-dontstarvetogether {
    backdrop-filter: saturate(70%);
  }
  .server-gmod {
    backdrop-filter: saturate(40%);
  }
}

.server-type-icon .server {
  position: relative;

  @mixin server-type-icon(\\$url) {
    padding-right: 4em !important;
    filter: saturate(0.75);
    .chip { display: none }
    &::after {
      content: '';
      background: url(\\$url);
      height: 3em;
      width: 3em;
      display: block;
      background-size: contain;
      color: transparent;
      position: absolute;
      top: 0.625em;
      right: 0.625em;
      filter: var(--servertype-icon-filter);
    }
  }

  @each \\$type in \\$serverTypes {
    &.server-#{\\$type} {
      @include server-type-icon('/img/icons/' + \\$type + '.png');
    }
  }

  @mixin status-indicator(\\$rad: 0.75em) {
    @include icon-base;
    position: absolute;
    top: 0.24em;
    right: 0.24em;
    font-size: 1.5em;
    line-height: 1em;
    height: 1em;
    width: 1em;
    z-index: 1;
    background-color: var(--background);
    border-radius: \\$rad;
  }

  &[data-online="installing"]::before {
    @include status-indicator(\\$rad: 4px);
    @include icon-name-base(package-down);
    color: var(--primary);
  }

  &[data-online="online"]::before {
    @include status-indicator;
    @include icon-name-base(play-circle);
    color: var(--primary);
  }

  &[data-online="offline"]::before {
    @include status-indicator;
    @include icon-name-base(stop-circle);
    color: var(--text-disabled);
  }

  &[data-online="loading"]::before {
    @include status-indicator;
    @include icon-name-base(loading);
    @include icon-spin-base;
  }
}

.server-type-icon .global-search .server {
  @each \\$type in \\$serverTypes {
    &.server-#{\\$type}::after {
      top: -0.125em;
      height: 2.5em;
      width: 2.5em;
    }
  }
}

html[dir="rtl"] {
  .server-type-none .server {
    padding-left: 4em;
    &[data-online="installing"]::before, &[data-online="online"]::before, &[data-online="offline"]::before, &[data-online="loading"]::before {
      left: 0.2em;
      right: unset;
    }
  }

  .server-type-icon .server {
    @mixin server-type-icon {
      padding-left: 4em;
      &::after {
        left: 0.625em;
        right: unset;
      }
    }

    @each \\$type in \\$serverTypes {
      &.server-#{\\$type} {
        @include server-type-icon;
      }
    }

    @mixin status-indicator {
      left: 0.24em;
      right: unset;
    }

    &[data-online="installing"]::before, &[data-online="online"]::before, &[data-online="offline"]::before, &[data-online="loading"]::before {
      @include status-indicator;
    }
  }
}

@include high-contrast-mode {
  .server[data-online="offline"]::before {
    color: var(--text);
  }
}

