.nodeview, .nodecreate {
  @include card;
}

.nodeview .overlay{
  width: 85vw;
}

.servercreate {
  @include card;
  @include cols(12);

  .progress {
    display: flex;
    justify-content: space-evenly;
    position: relative;

    &::before {
      display: block;
      content: '';
      height: 0.25em;
      background-color: var(--primary);
      position: absolute;
      left: 0;
      top: calc(50% - 0.125em);
      transition: width 0.1s ease-in-out;
    }

    &::after {
      display: block;
      content: '';
      height: 0.25em;
      background-color: var(--primary-hover);
      position: absolute;
      right: 0;
      top: calc(50% - 0.125em);
      transition: width 0.1s ease-in-out;
    }

    .step {
      @include icon;
      @include icon-name(check);
      & {
        font-size: 1.5em;
        line-height: 2rem;
        text-align: center;
        width: 2rem;
        height: 2rem;
        border-radius: 1rem;
        background-color: var(--primary);
        z-index: 1;
      }
      &::before {
        color: var(--text-primary);
      }
    }

    @mixin step-icons {
      &.step-template {
        @include icon-name(file-code);
      }
      &.step-environment {
        @include icon-name(cube-outline);
