  switch(o.type) {
    case "download":
      c = Array.isArray(o.files) ? o.files.length : 1
      if (c === 1) params.file = Array.isArray(o.files) ? o.files[0] : o.files
      return t(\\`operators.\\${o.type}.formatted\\`, params, c)
