      disabled
      type="email"
      :label="t('users.Email')"
      icon="email"
      :error="errorEmail"
      @change="errorEmail = ''"
      @blur="checkEmail()"
    />
    <text-field
      v-model="password"
      type="password"
      :label="t('users.Password')"
      icon="lock"
      :error="errorPassword"
      @change="errorPassword = ''"
      @blur="checkPassword()"
    />
    <text-field
