      icon: 'remove',
      color: 'error',
      action: async () => {
        await api.template.deleteRepo(repo.id)
        await loadTemplates()
      }
    },
    {
      color: 'primary'
    }
  )
}

async function addRepo() {
  await api.template.addRepo({...currentRepo.value, isLocal: false, id: 2})
  resetAddRepo()
  await loadTemplates()
}

function resetAddRepo() {
  currentRepo.value = {name: '', url: '', branch: ''}
