# cmd/dbupgrade.go (2.4 KB)
cat <<EOL > "cmd/dbupgrade.go"
package main

import (
	"fmt"
	"github.com/mattn/go-sqlite3"
	"github.com/pterm/pterm"
	"github.com/pufferpanel/pufferpanel/v3/config"
	"github.com/pufferpanel/pufferpanel/v3/database"
	"github.com/pufferpanel/pufferpanel/v3/utils"
	"github.com/spf13/cobra"
	"io"
	"os"
	"path/filepath"
)

var dbUpgradeCmd = &cobra.Command{
	Use:   "upgrade",
	Short: "Runs the database upgrades",
	Run:   executeDbUpgrade,
}

func executeDbUpgrade(cmd *cobra.Command, args []string) {
	var currentFile string
	var backupFile string

	if !config.PanelEnabled.Value() {
		pterm.Info.Printfln("Panel not enabled, skipping upgrade")
		os.Exit(0)
	}

	if database.GetDialect() == "sqlite3" {
		//we could get the filename... let's get it
		drv := sqlite3.SQLiteDriver{}
		conn, err := drv.Open(database.GetConnectionString())
		if err != nil {
			pterm.Error.Printfln("error connecting to database: %s", err.Error())
			os.Exit(1)
			return
		}
		s3 := conn.(*sqlite3.SQLiteConn)
		currentFile = s3.GetFilename("")
		_ = conn.Close()

		//look for a new name we can give this....
		suffix := "backup"
		num := 0
		for {
			backupFile = fmt.Sprintf("%s.%d.%s", currentFile, num, suffix)
			fi, err := os.Lstat(backupFile)
			if os.IsNotExist(err) && fi == nil {
				break
			}
			num++
		}

		err = copyDatabaseFile(currentFile, backupFile)
		if err != nil {
			pterm.Error.Printfln("error backing up database: %s", err.Error())
			os.Exit(1)
			return
		}
	}

	db, err := database.GetConnection()
	if err != nil {
		pterm.Error.Printfln("error connecting to database: %s", err.Error())
		rollback(backupFile, currentFile)
		os.Exit(1)
		return
	}

	pterm.Info.Printfln("Starting database upgrade")
	err = database.Upgrade(db, true)
	if err != nil {
		pterm.Error.Printfln("Database upgrade failed: %s", err.Error())
		rollback(backupFile, currentFile)
		os.Exit(1)
		return
	}
}

func rollback(backup, overrideTo string) {
	if backup == "" || overrideTo == "" {
		return
	}
	err := copyDatabaseFile(backup, overrideTo)
	if err != nil {
		pterm.Error.Printfln("error restoring database: %s", err.Error())
		return
	}
}

func copyDatabaseFile(src, dest string) error {
	source, err := os.Open(src)
	if err != nil {
		return err
	}
	defer utils.Close(source)

	err = os.MkdirAll(filepath.Dir(dest), 0750)
	if err != nil {
		return err
	}
	destination, err := os.Create(dest)
	if err != nil {
		return err
	}
	defer utils.Close(destination)
	_, err = io.Copy(destination, source)
	return err
}

EOL

# cmd/main.go (1.5 KB)
cat <<EOL > "cmd/main.go"
package main

import (
	"fmt"
	"github.com/pufferpanel/pufferpanel/v3"
	"github.com/pufferpanel/pufferpanel/v3/config"
	"github.com/pufferpanel/pufferpanel/v3/logging"
	"github.com/spf13/cobra"
	"os"
	"runtime/debug"
)

func main() {
	/*if !groups.IsUserIn(groups.PufferPanelGroup) {
		fmt.Println("You do not have permission to use this command")
		return
	}*/

	defer logging.Close()

	defer func() {
		if err := recover(); err != nil {
			stacktrace := debug.Stack()
			logging.Error.Printf("%s\\n%s\\n", err, stacktrace)

			os.Exit(2)
		}
	}()

	Execute()
}

var rootCmd = &cobra.Command{
	Use:   "pufferpanel",
	Short: "Game Server Management Panel",
	CompletionOptions: cobra.CompletionOptions{
		DisableDefaultCmd: true,
	},
}

var configFile string
var workDir string

func init() {
	rootCmd.PersistentFlags().StringVar(&workDir, "workDir", "", "Set working directory")
	rootCmd.PersistentFlags().StringVar(&configFile, "config", "", "Location of config")

	cobra.OnInitialize(setWorkDir, loadConfig)

	rootCmd.AddCommand(
		runCmd,
		versionCmd,
		userCmd,
		runServiceCmd,
		dbCmd,
	)
}

func setWorkDir() {
	if workDir != "" {
		err := os.Chdir(workDir)
		if err != nil {
			panic(err)
		}
	}
}

func loadConfig() {
	err := config.LoadConfigFile(configFile)
	if err != nil {
		fmt.Printf("Error loading config, this may impact features:\\n%s\\n", err.Error())
	}
}

func Execute() {
	rootCmd.SetVersionTemplate(pufferpanel.Display)

	if err := rootCmd.Execute(); err != nil {
		fmt.Println(err)
	}
}

