cat <<EOL > "logging/multi.go"
// Copyright 2010 The Go Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

//This is an altered variant of the MultiWriter provided by Golang.
//This adds a null-check to adding writings, along with holding off
//on returning when doing a write so that things don't look stupid....
//because windows

package logging

import (
	"io"
	"reflect"
)

type multiWriter struct {
	writers []io.Writer
}

func (t *multiWriter) Write(p []byte) (n int, err error) {
	for _, w := range t.writers {
		if w == nil {
			continue
		}
		n, err = w.Write(p)
		if err != nil {
			return
		}
		if n != len(p) {
			err = io.ErrShortWrite
			return
		}
	}
	return len(p), nil
}

var _ io.StringWriter = (*multiWriter)(nil)

func (t *multiWriter) WriteString(s string) (n int, err error) {
	var p []byte // lazily initialized if/when needed
	var firstErr error
	for _, w := range t.writers {
		if sw, ok := w.(io.StringWriter); ok {
			n, err = sw.WriteString(s)
		} else {
			if p == nil {
				p = []byte(s)
			}
			n, err = w.Write(p)
		}
		if err == nil && n != len(s) {
			err = io.ErrShortWrite
		}
		if firstErr == nil && err != nil {
			firstErr = err
		}
	}
	return len(s), firstErr
}

// MultiWriter creates a writer that duplicates its writes to all the
// provided writers, similar to the Unix tee(1) command.
//
// Each write is written to each listed writer, one at a time.
// If a listed writer returns an error, that overall write operation
// stops and returns the error; it does not continue down the list.
func MultiWriter(writers ...io.Writer) io.Writer {
	allWriters := make([]io.Writer, 0, len(writers))
	for _, w := range writers {
		if isNull(w) {
			continue
		}
		if mw, ok := w.(*multiWriter); ok {
			allWriters = append(allWriters, mw.writers...)
		} else {
			allWriters = append(allWriters, w)
		}
	}
	return &multiWriter{allWriters}
}

func isNull(val any) bool {
	if val == nil {
		return true
	}

	v := reflect.ValueOf(val)
	k := v.Kind()
	switch k {
	case reflect.Chan, reflect.Func, reflect.Map, reflect.Pointer,
		reflect.UnsafePointer, reflect.Interface, reflect.Slice:
		return v.IsNil()
	}

	return false
}

EOL

# logging/rotator.go (929 bytes)
cat <<EOL > "logging/rotator.go"
package logging

import (
	"io"
	"os"
	"os/signal"
	"path"
	"sync"
	"syscall"
)

type Rotator struct {
	sync.RWMutex
	io.WriteCloser
	backer io.WriteCloser
}

func (r *Rotator) Write(p []byte) (n int, err error) {
	r.RLock()
	defer r.RUnlock()
	if r.backer == nil {
		return len(p), nil
	}
	return r.backer.Write(p)
}

func (r *Rotator) Close() error {
	if r.backer == nil {
		return nil
	}
	return r.backer.Close()
}

func (r *Rotator) Rotate(newBackend io.WriteCloser) {
	r.Lock()
	defer r.Unlock()
	oldBacker := r.backer
	r.backer = newBackend
	_ = oldBacker.Close()
}

func (r *Rotator) StartRotation(dir string) {
	go func(directory string) {
		sig := make(chan os.Signal, 1)
		for {
			signal.Notify(sig, syscall.SIGUSR1)

			<-sig

			newFile, err := os.OpenFile(path.Join(directory, "pufferpanel.log"), os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0644)
			if err != nil {
				panic(err)
			}

			r.Rotate(newFile)
		}
	}(dir)
}

EOL

