type Stdin struct {
	Command string
}

func (d Stdin) Run(args pufferpanel.RunOperatorArgs) pufferpanel.OperationResult {
	env := args.Environment

	running, err := env.IsRunning()
	if err != nil {
		return pufferpanel.OperationResult{Error: err}
