// Get Gets a specific OAuth client, including the scopes it holds
func (s *OAuth2) Get(clientId string) (*models.Client, error) {
	client := &models.Client{
		ClientId: clientId,
	}
	err := s.DB.Where(client).First(client).Error
	return client, err
}

