// @Failure 404 {object} pufferpanel.ErrorResponse
// @Failure 500 {object} pufferpanel.ErrorResponse
// @Param id path uint true "User ID"
// @Router /api/users/{id} [get]
// @Security OAuth2Application[users.info.view]
